134	func (s *Server) getInvoiceLines(w http.ResponseWriter, r *http.Request, p auth.Principal) {
135		inv, ok := s.store.InvoiceByID(r.PathValue("id"))
136		if !ok {
137			writeError(w, http.StatusNotFound, "not_found", "no such invoice")
138			return
139		}
140		type lineView struct {
141			store.Line
142			Amount int64 `json:"amount"`
143		}
144		items := []lineView{}
145		for _, l := range inv.Lines {
146			items = append(items, lineView{Line: l, Amount: l.Amount()})
147		}
148		writeJSON(w, http.StatusOK, list{Items: items})
149	}
