package api_test

import (
	"bytes"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"math/rand"
	"net/http"
	"os"
	"testing"
	"time"

	"example.com/tally/internal/apitest"
	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// TEMPORARY golden recorder: writes every list answer of a deterministic fixture to $GOLDEN_OUT.
func TestZZGolden(t *testing.T) {
	out := os.Getenv("GOLDEN_OUT")
	if out == "" {
		t.Skip()
	}
	e := apitest.New(t)
	rng := rand.New(rand.NewSource(7))
	base := apitest.Start
	var buf bytes.Buffer
	rec := func(method, path, key string) *apitest.Response {
		r := e.Do(method, path, key, nil)
		fmt.Fprintf(&buf, "%s %s %d %s\n", method, path, r.Code, r.Body)
		return r
	}
	// Customers: some share a creation time; some are deleted later.
	var custs []store.Customer
	for i := 0; i < 120; i++ {
		c, err := e.Store.CreateCustomer(e.Acme.ID, fmt.Sprintf("C%03d", i), fmt.Sprintf("c%03d@acme.example", i), base.Add(time.Duration(i/3)*time.Second))
		if err != nil {
			t.Fatal(err)
		}
		custs = append(custs, c)
	}
	var globexCusts []store.Customer
	for i := 0; i < 10; i++ {
		c, _ := e.Store.CreateCustomer(e.Globex.ID, fmt.Sprintf("G%03d", i), fmt.Sprintf("g%03d@globex.example", i), base)
		globexCusts = append(globexCusts, c)
	}
	plan, _ := e.Store.CreatePlan(store.Plan{OrgID: e.Acme.ID, Name: "P", Currency: money.USD, UnitAmount: 1000, Interval: store.Monthly}, base)
	var subs []store.Subscription
	for i := 0; i < 15; i++ {
		s, err := e.Store.CreateSubscription(store.Subscription{OrgID: e.Acme.ID, CustomerID: custs[i].ID, PlanID: plan.ID, Quantity: 1, Status: store.Active,
			StartedAt: base, CurrentPeriodStart: base, CurrentPeriodEnd: base.AddDate(0, 1, 0)}, base)
		if err != nil {
			t.Fatal(err)
		}
		subs = append(subs, s)
	}
	mk := func(org store.Org, c store.Customer, sub string, at time.Time) store.Invoice {
		lines := []store.Line{{Description: "seat", Quantity: int64(1 + rng.Intn(3)), UnitAmount: int64(100 + rng.Intn(900))}}
		if rng.Intn(3) == 0 {
			lines = append(lines, store.Line{Description: "extra", Quantity: 2, UnitAmount: 50})
		}
		if rng.Intn(10) == 0 {
			lines = append(lines, store.Line{Description: "credit", Quantity: 1, UnitAmount: -25})
		}
		cur := money.USD
		if rng.Intn(4) == 0 {
			cur = money.EUR
		}
		inv, err := e.Store.CreateInvoice(store.Invoice{OrgID: org.ID, CustomerID: c.ID, SubscriptionID: sub, Currency: cur, Lines: lines, DiscountPercent: rng.Intn(3) * 10}, at)
		if err != nil {
			t.Fatal(err)
		}
		return inv
	}
	var invs []store.Invoice
	for i := 0; i < 1500; i++ {
		at := base.Add(time.Duration(i/4) * time.Minute)
		if i%11 == 0 {
			at = base.Add(time.Duration(i) * time.Second / 3) // back-dated relative to neighbours
		}
		c := custs[rng.Intn(len(custs))]
		sub := ""
		if rng.Intn(3) == 0 && int(c.ID[len(c.ID)-1])%2 == 0 {
			sub = subs[rng.Intn(len(subs))].ID
		}
		if i%13 == 0 && len(subs) > 0 {
			sub = subs[i%len(subs)].ID
		}
		inv := mk(e.Acme, c, sub, at)
		invs = append(invs, inv)
		if i%5 == 0 {
			g := globexCusts[rng.Intn(len(globexCusts))]
			mk(e.Globex, g, "", at)
		}
	}
	for i, inv := range invs {
		switch i % 6 {
		case 1:
			e.Store.UpdateInvoice(e.Acme.ID, inv.ID, func(x *store.Invoice) error { x.Status = store.InvoicePaid; x.PaidAt = &base; return nil })
		case 3:
			e.Store.UpdateInvoice(e.Acme.ID, inv.ID, func(x *store.Invoice) error { x.Status = store.InvoiceVoid; x.VoidedAt = &base; return nil })
		}
	}
	// Delete some customers, so their invoices show a null customer.
	for i := 100; i < 120; i += 3 {
		e.Store.DeleteCustomer(e.Acme.ID, custs[i].ID)
	}

	filters := []string{
		"", "?status=open", "?status=paid", "?status=void", "?status=bad", "?customer_id=" + custs[5].ID, "?customer_id=" + custs[110].ID,
		"?customer_id=cus_nope", "?customer_id=" + globexCusts[0].ID, "?subscription_id=" + subs[0].ID, "?subscription_id=" + subs[3].ID,
		"?subscription_id=sub_nope", "?customer_id=" + custs[0].ID + "&status=open", "?subscription_id=" + subs[1].ID + "&status=void",
	}
	limits := []string{"", "&limit=1", "&limit=3", "&limit=50", "&limit=100", "&limit=0", "&limit=101", "&limit=abc"}
	for _, f := range filters {
		for _, l := range limits {
			sep := "?"
			if f != "" {
				sep = "&"
			}
			if f == "" && l != "" {
				sep = "?"
			}
			path := "/v1/invoices" + f + sep + l[min(1, len(l)):]
			if l == "" {
				path = "/v1/invoices" + f
			}
			rec("GET", path, e.Acme.Key)
		}
	}
	// Walk every filter with small pages; create invoices in the middle of one walk.
	for fi, f := range filters {
		sep := "?"
		if f != "" {
			sep = "&"
		}
		if f == "" {
			sep = "?"
		}
		cursor := ""
		for step := 0; step < 2000; step++ {
			path := "/v1/invoices" + f + sep + "limit=7"
			if cursor != "" {
				path += "&cursor=" + cursor
			}
			r := rec("GET", path, e.Acme.Key)
			var l struct {
				NextCursor string `json:"next_cursor"`
			}
			json.Unmarshal(r.Body, &l)
			if l.NextCursor == "" {
				break
			}
			cursor = l.NextCursor
			if fi == 0 && step == 10 {
				// Created between pages: one later, one back-dated before the cursor.
				mk(e.Acme, custs[1], "", base.Add(time.Hour))
				mk(e.Acme, custs[2], "", base.Add(time.Second))
			}
		}
	}
	// Hand-made cursors, and bad ones.
	for _, at := range []time.Time{base, base.Add(3 * time.Minute), base.Add(time.Hour * 5), base.Add(-time.Hour)} {
		for _, id := range []string{"in_000001", "in_000900", "zzz", "in_999999"} {
			raw, _ := json.Marshal(map[string]any{"t": at, "id": id})
			c := base64.RawURLEncoding.EncodeToString(raw)
			rec("GET", "/v1/invoices?limit=5&cursor="+c, e.Acme.Key)
			rec("GET", "/v1/invoices?status=open&limit=5&cursor="+c, e.Acme.Key)
		}
	}
	rec("GET", "/v1/invoices?cursor=!!!", e.Acme.Key)
	rec("GET", "/v1/invoices?cursor=", e.Acme.Key)
	rec("GET", "/v1/invoices?status=open", e.Globex.Key)
	rec("GET", "/v1/invoices", "")
	// Single invoices, for good measure.
	for _, inv := range invs[:50] {
		rec("GET", "/v1/invoices/"+inv.ID, e.Acme.Key)
	}
	if err := os.WriteFile(out, buf.Bytes(), 0o644); err != nil {
		t.Fatal(err)
	}
	_ = http.MethodGet
}

